      return;
    }
    this.adding = true;
    try {
      await this.reasons.add(reason);
      this.reason.set('');
    } catch {
      this.error.set(`The void reason could not be added: ${reason} may already be one.`);
    } finally {
      this.adding = false;
    }
  }
}
